/* --- Source: overview.js --- */
;
/**
 * Overview & True Net Worth Module
 * Manages KPI hero cards, trajectory charts, and granular asset allocation doughnut.
 */

var historicalNetWorthData = null, monthlyNetWorthData = null, quarterlyNetWorthData = null, historicalSavingsData = null;
var recommendedGranularity = 'annual', activeHistGranularity = null, activeProjGranularity = 'annual', overviewChartMode = 'projection';
var widgetEditModeByPage = { overview: false, scenarios: false }, widgetFetchAbortByPage = { overview: null, scenarios: null };
var draggedWidgetCard = null, dropTargetCard = null, dropInsertBefore = true;

function renderOverview(data) {
    const projLoader = document.getElementById('overview-chart-loading');
    const allocLoader = document.getElementById('overview-alloc-loading');
    const hideLoaders = (p, a) => {
        if (p && projLoader) { projLoader.classList.add('hidden'); projLoader.style.display = 'none'; }
        if (a && allocLoader) { allocLoader.classList.add('hidden'); allocLoader.style.display = 'none'; }
    };
    if (!data || !data.snapshot) { hideLoaders(true, true); return; }
    cachedSnapshot = data.snapshot;
    try {
        const series = (data.multi_year_projections && data.multi_year_projections.length > 0)
            ? buildProjectionSeriesForGranularity(data.multi_year_projections, activeProjGranularity) : [];
        renderProjectionChart(series);
    } catch (e) { console.error('Error rendering projection chart:', e); hideLoaders(true, false); }
    try { renderGranularAllocationChart(data.snapshot); } catch (e) { console.error('Error rendering allocation chart:', e); hideLoaders(false, true); }
    setupOverviewChartToggle();
    setupOverviewAllocToggle();
    applyWidgetEditModeUI('overview');
    if (typeof window !== 'undefined' && typeof window.hydrateWidgetCharts === 'function') window.hydrateWidgetCharts('overview');
}

function setupOverviewAllocToggle() {
    const btnTotal = document.getElementById('btn-alloc-total');
    const btnPublic = document.getElementById('btn-alloc-public');
    if (!btnTotal || !btnPublic) return;
    const setMode = (mode, activeBtn, otherBtn) => {
        overviewAllocMode = mode;
        activeBtn.classList.add('active');
        otherBtn.classList.remove('active');
        if (cachedSnapshot) renderGranularAllocationChart(cachedSnapshot);
    };
    btnTotal.onclick = () => setMode('total', btnTotal, btnPublic);
    btnPublic.onclick = () => setMode('public', btnPublic, btnTotal);
}

function getSeriesForGranularity(gran) {
    if (gran === 'monthly' && monthlyNetWorthData && monthlyNetWorthData.length) return monthlyNetWorthData;
    if (gran === 'quarterly' && quarterlyNetWorthData && quarterlyNetWorthData.length) return quarterlyNetWorthData;
    if (historicalNetWorthData && historicalNetWorthData.length) return historicalNetWorthData;
    if (monthlyNetWorthData && monthlyNetWorthData.length) return monthlyNetWorthData;
    return quarterlyNetWorthData || [];
}

function syncGranularityPillUI(gran) {
    const granContainer = document.getElementById('hist-granularity-controls');
    if (granContainer) granContainer.querySelectorAll('[data-granularity]').forEach(btn => btn.classList.toggle('active', btn.getAttribute('data-granularity') === gran));
}

function setupOverviewChartToggle() {
    const btnProj = document.getElementById('btn-chart-proj'), btnHist = document.getElementById('btn-chart-hist');
    const granContainer = document.getElementById('hist-granularity-controls');
    const titleEl = document.getElementById('overview-chart-title'), subEl = document.getElementById('overview-chart-sub');

    if (granContainer) {
        granContainer.style.display = 'inline-flex';
        granContainer.querySelectorAll('[data-granularity]').forEach(btn => {
            btn.onclick = () => {
                const gran = btn.getAttribute('data-granularity') || 'annual';
                syncGranularityPillUI(gran);
                if (overviewChartMode === 'projection') {
                    activeProjGranularity = gran;
                    if (window.globalProjections) renderProjectionChart(buildProjectionSeriesForGranularity(window.globalProjections, gran));
                } else {
                    activeHistGranularity = gran;
                    const series = getSeriesForGranularity(gran);
                    if (series && series.length) renderHistoricalChart(series);
                }
            };
        });
    }
    if (!btnProj || !btnHist) return;
    btnProj.onclick = () => {
        overviewChartMode = 'projection';
        btnProj.classList.add('active'); btnHist.classList.remove('active');
        if (granContainer) granContainer.style.display = 'inline-flex';
        syncGranularityPillUI(activeProjGranularity || 'annual');
        if (titleEl) titleEl.textContent = '5-Year Net Worth Trajectory';
        if (subEl) subEl.textContent = '5-year trajectory (Vested Net Worth + ongoing grant monthly vesting; unvested excluded until vested)';
        if (window.globalProjections) renderProjectionChart(buildProjectionSeriesForGranularity(window.globalProjections, activeProjGranularity || 'annual'));
    };
    btnHist.onclick = async () => {
        overviewChartMode = 'historical';
        btnHist.classList.add('active'); btnProj.classList.remove('active');
        if (granContainer) granContainer.style.display = 'inline-flex';
        if (titleEl) titleEl.textContent = 'Historical Net Worth Trajectory';
        if (subEl) {
            const hasAdj = cachedSnapshot && cachedSnapshot.company_equity && ((cachedSnapshot.company_equity.total_strike_cost_needed || 0) > 0 || (cachedSnapshot.company_equity.total_tax_drag || 0) > 0);
            subEl.textContent = hasAdj ? 'Compound growth: Net Worth, company post-tax equity, and liquid investments' : 'Compound growth: Net Worth, company equity, and liquid investments';
        }
        const loader = document.getElementById('overview-chart-loading');
        if (!historicalNetWorthData) {
            if (loader) {
                const textEl = loader.querySelector('.chart-loading-text');
                if (textEl) textEl.textContent = 'Loading Historical Net Worth...';
                loader.classList.remove('hidden'); loader.style.display = 'flex';
            }
            try {
                const res = await (await fetch('/api/networth/history')).json();
                if (res.success) {
                    historicalNetWorthData = res.historical_net_worth || [];
                    monthlyNetWorthData = res.monthly_net_worth || [];
                    quarterlyNetWorthData = res.quarterly_net_worth || [];
                    recommendedGranularity = res.recommended_granularity || 'annual';
                    historicalSavingsData = res.annual_savings_history || [];
                }
            } catch (e) { console.error('History fetch failed:', e); }
        }
        if (!activeHistGranularity) activeHistGranularity = recommendedGranularity || 'annual';
        syncGranularityPillUI(activeHistGranularity);
        const activeSeries = getSeriesForGranularity(activeHistGranularity);
        if (activeSeries && activeSeries.length) renderHistoricalChart(activeSeries);
        else if (loader) loader.classList.add('hidden');
    };
}

function getActiveWidgetIdsForPage(page) {
    const drawer = document.getElementById(`widget-customizer-drawer-${page}`);
    if (drawer && drawer.dataset.activeIds !== undefined) {
        return drawer.dataset.activeIds.split(',').map(s => s.trim()).filter(Boolean);
    }
    const grid = document.getElementById(page === 'overview' ? 'overview-widgets-grid' : 'scenarios-widgets-grid');
    return grid ? Array.from(grid.querySelectorAll('.household-widget-card[data-widget-id]')).map(el => el.getAttribute('data-widget-id')).filter(Boolean) : [];
}

function isDemoOrReadOnlySession() {
    if (typeof window !== 'undefined' && typeof window.isDemoSession === 'function' && window.isDemoSession()) return true;
    if (typeof document !== 'undefined' && document.body && (document.body.dataset.isDemo === 'true' || document.body.dataset.role === 'viewer')) return true;
    return Boolean(typeof window !== 'undefined' && window.location && new URLSearchParams(window.location.search).get('demo') === '1');
}

function applyWidgetEditModeUI(page) {
    if (typeof document === 'undefined') return;
    const isEdit = Boolean(widgetEditModeByPage[page]), drawer = document.getElementById(`widget-customizer-drawer-${page}`);
    if (drawer) drawer.style.display = isEdit ? 'block' : 'none';
    document.querySelectorAll(`.btn-toggle-widget-drawer[data-page="${page}"]`).forEach(btn => { if (!drawer || !drawer.contains(btn)) btn.style.display = isEdit ? 'none' : 'inline-flex'; });
    const grid = document.getElementById(page === 'overview' ? 'overview-widgets-grid' : 'scenarios-widgets-grid');
    if (grid) {
        grid.classList.toggle('widget-edit-mode-active', isEdit);
        grid.querySelectorAll('.household-widget-card[data-widget-id]').forEach(card => {
            card.setAttribute('draggable', isEdit ? 'true' : 'false');
            card.style.outline = isEdit ? '1px dashed rgba(59, 130, 246, 0.5)' : '';
            card.style.outlineOffset = isEdit ? '2px' : '';
            card.style.transition = 'transform 0.15s ease, outline 0.15s ease';
        });
    }
    document.querySelectorAll(`.widget-inline-actions[data-page="${page}"]`).forEach(el => { el.style.display = isEdit ? 'inline-flex' : 'none'; });
}

function setWidgetEditMode(page, enabled) {
    if (!page) return;
    widgetEditModeByPage[page] = Boolean(enabled);
    applyWidgetEditModeUI(page);
}

function syncDrawerCatalogOrder(page, orderedIds, syncCheckboxes = false) {
    const drawer = document.getElementById(`widget-customizer-drawer-${page}`);
    if (drawer && Array.isArray(orderedIds)) {
        drawer.dataset.activeIds = orderedIds.join(',');
        const chks = Array.from(drawer.querySelectorAll('.chk-widget-toggle'));
        if (syncCheckboxes) chks.forEach(chk => { if (!chk.disabled) chk.checked = orderedIds.includes(chk.getAttribute('data-widget-id')); });
        const inactive = chks.filter(c => !orderedIds.includes(c.getAttribute('data-widget-id'))).map(c => c.getAttribute('data-widget-title') || '');
        document.querySelectorAll(`.widget-avail-badge[data-page="${page}"]`).forEach(b => { b.textContent = `+${inactive.length}`; b.style.display = inactive.length > 0 ? '' : 'none'; });
        document.querySelectorAll(`.widget-avail-summary[data-page="${page}"]`).forEach(s => {
            s.innerHTML = inactive.length ? `<span><strong>${inactive.length} additional graph${inactive.length !== 1 ? 's' : ''} &amp; widgets available:</strong> ${inactive.slice(0, 3).map(escapeHtml).join(' • ')}${inactive.length > 3 ? ` + ${inactive.length - 3} more` : ''}</span>` : `<span>All ${chks.length} widgets are active.</span>`;
        });
    }
    if (page === 'scenarios' && Array.isArray(orderedIds)) {
        const lbl = document.getElementById('scenarios-widgets-active-label');
        if (lbl) lbl.textContent = `FORECASTING GRAPHS & WIDGETS (${orderedIds.length} ACTIVE)`;
    }
}

function removeWidgetCardInPlace(page, wid, nextIds) {
    const grid = document.getElementById(page === 'overview' ? 'overview-widgets-grid' : 'scenarios-widgets-grid');
    const card = grid && grid.querySelector(`.household-widget-card[data-widget-id="${wid}"]`);
    if (card) card.remove();
    syncDrawerCatalogOrder(page, nextIds, true);
}

function setDemoWidgetCookie(page, widgetParam) {
    if (typeof document === 'undefined') return;
    try {
        const k = `hvl_widgets_${page}`;
        document.cookie = (!widgetParam || widgetParam === 'default') ? `${k}=; path=/; max-age=0; SameSite=Lax` : `${k}=${encodeURIComponent(widgetParam)}; path=/; max-age=604800; SameSite=Lax`;
    } catch (e) {}
}

async function refreshWidgetGridHtmlOnly(page, widgetParam) {
    if (widgetFetchAbortByPage[page]) widgetFetchAbortByPage[page].abort();
    const ctrl = typeof AbortController !== 'undefined' ? new AbortController() : null;
    widgetFetchAbortByPage[page] = ctrl;
    const base = `/fragments/${page}` + (widgetParam ? `?widgets=${encodeURIComponent(widgetParam)}` : '');
    const resp = await fetch(typeof appendSessionQuery === 'function' ? appendSessionQuery(base) : base, ctrl ? { signal: ctrl.signal } : {});
    if (!resp.ok || typeof DOMParser === 'undefined') return;
    const doc = new DOMParser().parseFromString(await resp.text(), 'text/html');
    const newChartScript = doc.getElementById(`ssr-widget-charts-data-${page}`), liveChartScript = document.getElementById(`ssr-widget-charts-data-${page}`);
    if (newChartScript && liveChartScript) liveChartScript.textContent = newChartScript.textContent;
    if (widgetParam === 'default') {
        const newDrawer = doc.getElementById(`widget-customizer-drawer-${page}`);
        if (newDrawer && newDrawer.dataset.activeIds !== undefined) syncDrawerCatalogOrder(page, newDrawer.dataset.activeIds.split(',').map(s => s.trim()).filter(Boolean), true);
    }
    const gridId = page === 'overview' ? 'overview-widgets-grid' : 'scenarios-widgets-grid';
    const newGrid = doc.getElementById(gridId), liveGrid = document.getElementById(gridId);
    if (!newGrid || !liveGrid) return;
    liveGrid.innerHTML = newGrid.innerHTML;
    const latestIds = getActiveWidgetIdsForPage(page);
    if (latestIds.length) liveGrid.querySelectorAll('.household-widget-card[data-widget-id]').forEach(c => { if (!latestIds.includes(c.getAttribute('data-widget-id'))) c.remove(); });
    applyWidgetEditModeUI(page);
    if (page === 'overview' && typeof renderOverview === 'function' && window.globalDashboardData) renderOverview(window.globalDashboardData);
    if (typeof window !== 'undefined' && typeof window.hydrateWidgetCharts === 'function') window.hydrateWidgetCharts(page);
}

async function saveHouseholdWidgetPreferences(page, activeIds, reset = false, options = {}) {
    const reorderOnly = Boolean(options && options.reorderOnly);
    if (Array.isArray(activeIds)) syncDrawerCatalogOrder(page, activeIds);
    if (isDemoOrReadOnlySession()) {
        const widgetParam = reset ? 'default' : (Array.isArray(activeIds) && activeIds.length ? activeIds.join(',') : 'none');
        if (page === 'scenarios') window.__demoWidgetsScenarios = widgetParam === 'default' ? undefined : widgetParam;
        if (page === 'overview') window.__demoWidgetsOverview = widgetParam === 'default' ? undefined : widgetParam;
        setDemoWidgetCookie(page, widgetParam);
        if (reorderOnly) { applyWidgetEditModeUI(page); return; }
        try { await refreshWidgetGridHtmlOnly(page, widgetParam); } catch (e) { if (e.name !== 'AbortError') console.error(e); }
        return;
    }
    try {
        const resp = await fetch('/api/widgets/preferences', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ page, active_ids: activeIds, reset: Boolean(reset), reorder_only: true }),
            skipReactiveMorph: true,
        });
        if (!resp.ok) return;
        const res = await resp.json().catch(() => ({}));
        if (reset && Array.isArray(res.active_ids)) syncDrawerCatalogOrder(page, res.active_ids, true);
        if (!reorderOnly) await refreshWidgetGridHtmlOnly(page);
        applyWidgetEditModeUI(page);
    } catch (e) { if (e.name !== 'AbortError') console.error('Failed to save widget preferences:', e); }
}

function initHouseholdWidgetsDelegation() {
    if (typeof document === 'undefined' || document._householdWidgetsWired) return;
    document._householdWidgetsWired = true;

    document.addEventListener('click', (e) => {
        if (e.target.closest('.nav-link[data-target], .nav-item[data-target]')) {
            if (widgetEditModeByPage.overview) setWidgetEditMode('overview', false);
            if (widgetEditModeByPage.scenarios) setWidgetEditMode('scenarios', false);
            return;
        }
        const toggleBtn = e.target.closest('.btn-toggle-widget-drawer');
        if (toggleBtn) {
            const p = toggleBtn.getAttribute('data-page'), next = !widgetEditModeByPage[p];
            setWidgetEditMode(p, next);
            const drw = next && document.getElementById(`widget-customizer-drawer-${p}`);
            if (drw && typeof drw.scrollIntoView === 'function') drw.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
            return;
        }
        const removeBtn = e.target.closest('.btn-widget-remove');
        if (removeBtn) {
            const page = removeBtn.getAttribute('data-page'), wid = removeBtn.getAttribute('data-widget-id');
            const nextIds = getActiveWidgetIdsForPage(page).filter(id => id !== wid);
            removeWidgetCardInPlace(page, wid, nextIds);
            saveHouseholdWidgetPreferences(page, nextIds, false, { reorderOnly: true });
            return;
        }
        const resetBtn = e.target.closest('.btn-widget-reset');
        if (resetBtn) {
            const rPage = resetBtn.getAttribute('data-page');
            if (typeof window.insertWidgetLoadingPlaceholder === 'function') window.insertWidgetLoadingPlaceholder(rPage, '', 'Default Widgets', true);
            saveHouseholdWidgetPreferences(rPage, null, true);
        }
    });

    document.addEventListener('change', (e) => {
        if (e.target && e.target.id === 'mobile-nav-select') {
            if (widgetEditModeByPage.overview) setWidgetEditMode('overview', false);
            if (widgetEditModeByPage.scenarios) setWidgetEditMode('scenarios', false);
            return;
        }
        const chk = e.target.closest('.chk-widget-toggle');
        if (!chk || chk.disabled || chk.dataset.core === 'true') return;
        const page = chk.getAttribute('data-page'), wid = chk.getAttribute('data-widget-id'), curIds = getActiveWidgetIdsForPage(page);
        if (!chk.checked) {
            const nextIds = curIds.filter(id => id !== wid);
            removeWidgetCardInPlace(page, wid, nextIds);
            saveHouseholdWidgetPreferences(page, nextIds, false, { reorderOnly: true });
        } else {
            if (typeof window.insertWidgetLoadingPlaceholder === 'function') {
                const title = chk.getAttribute('data-widget-title') || (chk.closest('.widget-catalog-item')?.querySelector('strong')?.textContent) || 'Widget';
                window.insertWidgetLoadingPlaceholder(page, wid, title, chk.getAttribute('data-full-width') === 'true');
            }
            saveHouseholdWidgetPreferences(page, curIds.includes(wid) ? curIds : [...curIds, wid], false, { reorderOnly: false });
        }
    });

    document.addEventListener('keydown', (e) => {
        const handle = e.target.closest('.widget-drag-handle');
        if (!handle || !['ArrowLeft', 'ArrowUp', 'ArrowRight', 'ArrowDown'].includes(e.key)) return;
        e.preventDefault();
        const page = handle.getAttribute('data-page');
        if (!widgetEditModeByPage[page]) return;
        const card = handle.closest('.household-widget-card[data-widget-id]'), grid = card && card.parentElement;
        if (!card || !grid) return;
        const cards = Array.from(grid.querySelectorAll('.household-widget-card[data-widget-id]')), idx = cards.indexOf(card);
        const dir = (e.key === 'ArrowLeft' || e.key === 'ArrowUp') ? -1 : 1, targetIdx = idx + dir;
        if (targetIdx < 0 || targetIdx >= cards.length) return;
        grid.insertBefore(card, dir < 0 ? cards[targetIdx] : cards[targetIdx].nextSibling);
        handle.focus();
        saveHouseholdWidgetPreferences(page, Array.from(grid.querySelectorAll('.household-widget-card[data-widget-id]')).map(c => c.getAttribute('data-widget-id')), false, { reorderOnly: true });
    });

    let lastSwapTs = 0, dragInitialOrder = '';
    const liveReorderOnDrag = (clientY, targetEl) => {
        const grid = draggedWidgetCard && draggedWidgetCard.parentElement;
        if (!grid || Date.now() - lastSwapTs < 75) return;
        const cards = Array.from(grid.querySelectorAll('.household-widget-card[data-widget-id]'));
        if (!cards.length) return;
        const firstCard = cards[0], firstRect = firstCard.getBoundingClientRect();
        if (clientY < firstRect.top + firstRect.height * 0.42) {
            if (firstCard !== draggedWidgetCard) { grid.insertBefore(draggedWidgetCard, firstCard); lastSwapTs = Date.now(); }
            return;
        }
        const hovered = targetEl && targetEl.closest ? targetEl.closest('.household-widget-card[data-widget-id]') : null;
        if (!hovered || hovered === draggedWidgetCard || hovered.parentElement !== grid) return;
        const rect = hovered.getBoundingClientRect(), relY = clientY - rect.top;
        if (relY < rect.height * 0.42 && hovered.previousElementSibling !== draggedWidgetCard) {
            grid.insertBefore(draggedWidgetCard, hovered); lastSwapTs = Date.now();
        } else if (relY > rect.height * 0.58 && hovered.nextElementSibling !== draggedWidgetCard) {
            grid.insertBefore(draggedWidgetCard, hovered.nextSibling); lastSwapTs = Date.now();
        }
    };

    const startCardDrag = (card) => {
        draggedWidgetCard = card; lastSwapTs = 0;
        const grid = card.parentElement;
        dragInitialOrder = grid ? Array.from(grid.querySelectorAll('.household-widget-card[data-widget-id]')).map(el => el.getAttribute('data-widget-id')).join(',') : '';
        card.style.opacity = '0.6'; card.style.outline = '2px solid #3B82F6';
    };

    const finishWidgetDrag = () => {
        if (!draggedWidgetCard) return;
        const card = draggedWidgetCard, grid = card.parentElement;
        draggedWidgetCard = null; card.style.opacity = '';
        if (!grid) return;
        const page = grid.id === 'overview-widgets-grid' ? 'overview' : 'scenarios';
        applyWidgetEditModeUI(page);
        const nextIds = Array.from(grid.querySelectorAll('.household-widget-card[data-widget-id]')).map(el => el.getAttribute('data-widget-id')).filter(Boolean);
        if (nextIds.join(',') !== dragInitialOrder) saveHouseholdWidgetPreferences(page, nextIds, false, { reorderOnly: true });
    };

    document.addEventListener('dragstart', (e) => {
        const card = e.target.closest('.household-widget-card[data-widget-id]');
        if (!card) return;
        const page = card.parentElement && card.parentElement.id === 'overview-widgets-grid' ? 'overview' : 'scenarios';
        if (!widgetEditModeByPage[page]) { e.preventDefault(); return; }
        startCardDrag(card);
        if (e.dataTransfer) { e.dataTransfer.effectAllowed = 'move'; e.dataTransfer.setData('text/plain', card.getAttribute('data-widget-id') || ''); }
    });
    document.addEventListener('dragover', (e) => { if (draggedWidgetCard) { e.preventDefault(); if (e.dataTransfer) e.dataTransfer.dropEffect = 'move'; liveReorderOnDrag(e.clientY, e.target); } });
    document.addEventListener('drop', (e) => { if (draggedWidgetCard) { e.preventDefault(); finishWidgetDrag(); } });
    document.addEventListener('dragend', finishWidgetDrag);
    document.addEventListener('touchstart', (e) => {
        const handle = e.target.closest('.widget-drag-handle'), card = handle && handle.closest('.household-widget-card[data-widget-id]');
        if (!card || !widgetEditModeByPage[handle.getAttribute('data-page')]) return;
        if (e.cancelable) e.preventDefault();
        startCardDrag(card);
    }, { passive: false });
    document.addEventListener('touchmove', (e) => {
        const t = draggedWidgetCard && e.touches && e.touches[0];
        if (!t) return;
        if (e.cancelable) e.preventDefault();
        if (typeof window.scrollBy === 'function') {
            const hdr = document.querySelector('.top-header'), topEdge = (hdr ? Math.max(0, hdr.getBoundingClientRect().bottom) : 0) + 55;
            if (t.clientY < topEdge) window.scrollBy(0, -16); else if (t.clientY > window.innerHeight - 85) window.scrollBy(0, 16);
        }
        liveReorderOnDrag(t.clientY, typeof document.elementFromPoint === 'function' ? document.elementFromPoint(t.clientX, t.clientY) : null);
    }, { passive: false });
    document.addEventListener('touchend', () => { if (draggedWidgetCard) finishWidgetDrag(); });
    document.addEventListener('touchcancel', () => { if (draggedWidgetCard) finishWidgetDrag(); });
}

if (typeof window !== 'undefined') {
    Object.assign(window, { renderOverview, setupOverviewChartToggle, setupOverviewAllocToggle, getSeriesForGranularity, syncGranularityPillUI, saveHouseholdWidgetPreferences, setWidgetEditMode, applyWidgetEditModeUI });
    initHouseholdWidgetsDelegation();
    if (typeof window.registerSectionHydrator === 'function') {
        window.registerSectionHydrator('section-overview', renderOverview, {
            needsDashboard: true,
            onInvalidate: () => { historicalNetWorthData = null; monthlyNetWorthData = null; quarterlyNetWorthData = null; historicalSavingsData = null; if (typeof cachedSnapshot !== 'undefined') cachedSnapshot = null; }
        });
    }
}

;

/* --- Source: widget_charts.js --- */
;
/**
 * Client-Side Chart Hydrator & Collapsible Chart Controller for Customizable Widgets.
 * Hydrates Overview charts (Lifetime Forecast, Cash Flow, Monte Carlo, Career Comp)
 * and Scenarios Companion charts (Cash Flow, Monte Carlo, Longevity).
 */
(function () {
    'use strict';
    const widgetCharts = {};
    let ovActiveScenId = null, ovViewMode = 'real';

    function fmtShort(v) {
        if (typeof window.fmtShortCurrency === 'function') return window.fmtShortCurrency(v);
        if (v == null) return '--';
        const num = Number(v);
        if (isNaN(num)) return '--';
        const abs = Math.abs(num), s = num < 0 ? '-' : '';
        if (abs >= 1e9) return `${s}$${(abs / 1e9).toFixed(2)}B`;
        if (abs >= 1e6) return `${s}$${(abs / 1e6).toFixed(2)}M`;
        if (abs >= 1e3) return `${s}$${(abs / 1e3).toFixed(0)}K`;
        return `${s}$${abs.toFixed(0)}`;
    }

    function getChartPayloads(page) {
        const el = document.getElementById(`ssr-widget-charts-data-${page}`);
        if (!el) return null;
        try { return JSON.parse(el.textContent || '{}'); } catch (e) { return null; }
    }

    function getStoredCollapsed() {
        try { const raw = localStorage.getItem('hvl_collapsed_charts'); return raw ? JSON.parse(raw) : []; }
        catch (e) { return []; }
    }

    function getStoredWidths() {
        try { const raw = localStorage.getItem('hvl_chart_widths'); return raw ? JSON.parse(raw) : {}; }
        catch (e) { return {}; }
    }

    function applyCollapsedState() {
        const stored = new Set(getStoredCollapsed());
        document.querySelectorAll('.btn-toggle-chart-collapse').forEach(btn => {
            const cId = btn.getAttribute('data-chart-id');
            const body = cId && document.querySelector(`.collapsible-chart-body[data-chart-body-id="${cId}"]`);
            if (!body) return;
            const isCol = stored.has(cId);
            body.style.display = isCol ? 'none' : '';
            btn.textContent = isCol ? 'Show Graph ▼' : 'Hide Graph ▲';
        });
    }

    function applyChartWidths() {
        const widths = getStoredWidths();
        document.querySelectorAll('.btn-toggle-chart-width').forEach(btn => {
            const cId = btn.getAttribute('data-chart-id');
            const card = cId && document.querySelector(`.household-widget-card[data-widget-id="${cId}"]`);
            if (!card) return;
            const defaultWide = card.getAttribute('data-default-wide') === 'true';
            const isWide = (cId in widths) ? Boolean(widths[cId]) : defaultWide;
            card.style.gridColumn = isWide ? '1 / -1' : '';
            btn.textContent = isWide ? '⇔ Half Width' : '⤢ Full Width';
        });
    }

    function toggleChartWidth(chartId) {
        if (!chartId) return;
        const card = document.querySelector(`.household-widget-card[data-widget-id="${chartId}"]`);
        const btn = document.querySelector(`.btn-toggle-chart-width[data-chart-id="${chartId}"]`);
        if (!card) return;
        const widths = getStoredWidths();
        const defaultWide = card.getAttribute('data-default-wide') === 'true';
        const curWide = (chartId in widths) ? Boolean(widths[chartId]) : defaultWide;
        const nextWide = !curWide;
        widths[chartId] = nextWide;
        try { localStorage.setItem('hvl_chart_widths', JSON.stringify(widths)); } catch (e) {}
        card.style.gridColumn = nextWide ? '1 / -1' : '';
        if (btn) btn.textContent = nextWide ? '⇔ Half Width' : '⤢ Full Width';
        Object.values(widgetCharts).forEach(ch => { if (ch && typeof ch.resize === 'function') ch.resize(); });
        const st = window.scenariosState;
        if (st) {
            [st.scenarioComparisonChart, st.cashFlowChart, st.longevityChart, st.monteCarloChart].forEach(ch => {
                if (ch && typeof ch.resize === 'function') ch.resize();
            });
        }
    }

    function toggleChartCollapse(chartId) {
        if (!chartId) return;
        const stored = new Set(getStoredCollapsed());
        const willCol = !stored.has(chartId);
        if (willCol) stored.add(chartId); else stored.delete(chartId);
        const arr = Array.from(stored);
        try {
            localStorage.setItem('hvl_collapsed_charts', JSON.stringify(arr));
            document.cookie = `hvl_collapsed_charts=${encodeURIComponent(arr.join(',') || 'none')}; path=/; max-age=604800; SameSite=Lax`;
        } catch (e) {}

        const body = document.querySelector(`.collapsible-chart-body[data-chart-body-id="${chartId}"]`);
        const btn = document.querySelector(`.btn-toggle-chart-collapse[data-chart-id="${chartId}"]`);
        if (body) body.style.display = willCol ? 'none' : '';
        if (btn) btn.textContent = willCol ? 'Show Graph ▼' : 'Hide Graph ▲';
        if (!willCol) window.hydrateWidgetCharts();

        if (typeof window.sessionIsDemo === 'undefined' || !window.sessionIsDemo) {
            fetch('/api/widgets/collapsed_charts', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ chart_id: chartId, collapsed: willCol })
            }).catch(() => {});
        }
    }

    function getOrCreateChart(canvasId, configBuilder) {
        const canvas = document.getElementById(canvasId);
        if (!canvas) return null;
        const body = canvas.closest('.collapsible-chart-body');
        if (body && body.style.display === 'none') return null;
        if (widgetCharts[canvasId]) { widgetCharts[canvasId].destroy(); delete widgetCharts[canvasId]; }
        const ctx = canvas.getContext('2d');
        if (!ctx) return null;
        const cfg = configBuilder(ctx);
        if (!cfg) return null;
        const chart = new Chart(ctx, cfg);
        widgetCharts[canvasId] = chart;
        return chart;
    }

    function baseOpts(extraScales = {}) {
        return {
            responsive: true, maintainAspectRatio: false,
            interaction: { mode: 'index', intersect: false },
            plugins: {
                legend: { position: 'top', labels: { color: '#94A3B8', font: { size: 10 } } },
                tooltip: { callbacks: { label: c => ` ${c.dataset.label}: ${fmtShort(c.raw)}` } }
            },
            scales: {
                x: { grid: { color: 'rgba(255, 255, 255, 0.05)' }, ticks: { color: '#94A3B8', maxTicksLimit: 11 } },
                y: { grid: { color: 'rgba(255, 255, 255, 0.05)' }, ticks: { color: '#94A3B8', callback: v => fmtShort(v) } },
                ...extraScales
            }
        };
    }

    function renderOvLifetimeForecast(payload) {
        const lf = payload?.lifetime_forecast;
        if (!lf?.years?.length) return;
        const isNom = ovViewMode === 'nominal', target = ovActiveScenId || lf.active_scenario_id;
        getOrCreateChart('chart-ov-lifetime-forecast', () => ({
            type: 'line',
            data: {
                labels: lf.years,
                datasets: (lf.scenarios || []).filter(s => target === 'all' || s.id === target).map(s => {
                    const col = s.color || (s.is_active ? '#3B82F6' : '#94A3B8');
                    return {
                        label: s.name + (isNom ? ' (Nominal)' : ' (Real)'),
                        data: isNom ? (s.net_worth_nominal || []) : (s.net_worth_real || []),
                        borderColor: col, backgroundColor: target !== 'all' ? (col + '1A') : 'transparent',
                        fill: target !== 'all', tension: 0.32, borderWidth: s.is_active ? 2.5 : 1.8, pointRadius: 0
                    };
                })
            },
            options: baseOpts()
        }));
    }

    function makeCfConfig(cf) {
        return {
            type: 'bar',
            data: {
                labels: cf.years,
                datasets: [
                    { label: 'Inflows', data: cf.inflows || [], backgroundColor: '#10B981', order: 2 },
                    { label: 'Living Spend', data: cf.living_spend || [], backgroundColor: 'rgba(239, 68, 68, 0.85)', order: 2 },
                    { label: 'Net Draw', data: cf.net_draw || [], type: 'line', borderColor: '#3B82F6', borderWidth: 2, tension: 0.28, pointRadius: 0, order: 1 }
                ]
            },
            options: baseOpts()
        };
    }

    function makeMcConfig(mc) {
        return {
            type: 'line',
            data: {
                labels: mc.years,
                datasets: [
                    { label: 'P90', data: mc.p90 || [], borderColor: '#10B981', borderDash: [4, 4], pointRadius: 0, borderWidth: 1.5 },
                    { label: 'P75', data: mc.p75 || [], borderColor: '#34D399', borderDash: [2, 2], pointRadius: 0, borderWidth: 1.2 },
                    { label: 'P50 (Median)', data: mc.p50 || [], borderColor: '#3B82F6', borderWidth: 2.5, pointRadius: 0 },
                    { label: 'P25', data: mc.p25 || [], borderColor: '#F59E0B', borderDash: [2, 2], pointRadius: 0, borderWidth: 1.2 },
                    { label: 'P10', data: mc.p10 || [], borderColor: '#EF4444', borderDash: [4, 4], pointRadius: 0, borderWidth: 1.5 }
                ]
            },
            options: baseOpts()
        };
    }

    function bindOverviewControls() {
        document.querySelectorAll('.ov-scen-switch-pill').forEach(btn => {
            btn.onclick = (e) => {
                e.preventDefault();
                document.querySelectorAll('.ov-scen-switch-pill').forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
                ovActiveScenId = btn.getAttribute('data-scen-id');
                const p = getChartPayloads('overview');
                if (p) renderOvLifetimeForecast(p);
            };
        });
        const rBtn = document.getElementById('btn-ov-lf-real'), nBtn = document.getElementById('btn-ov-lf-nominal');
        if (rBtn && nBtn) {
            rBtn.onclick = (e) => {
                e.preventDefault(); rBtn.classList.add('active'); nBtn.classList.remove('active');
                ovViewMode = 'real'; const p = getChartPayloads('overview'); if (p) renderOvLifetimeForecast(p);
            };
            nBtn.onclick = (e) => {
                e.preventDefault(); nBtn.classList.add('active'); rBtn.classList.remove('active');
                ovViewMode = 'nominal'; const p = getChartPayloads('overview'); if (p) renderOvLifetimeForecast(p);
            };
        }
    }

    window.insertWidgetLoadingPlaceholder = function (page, wid, title, fullWidth) {
        if (typeof document === 'undefined') return;
        const grid = document.getElementById(page === 'overview' ? 'overview-widgets-grid' : 'scenarios-widgets-grid');
        if (!grid || (wid && grid.querySelector(`.household-widget-card[data-widget-id="${wid}"]`))) return;
        const card = document.createElement('div');
        card.className = 'portal-card household-widget-card widget-loading-placeholder fragment-loading-skeleton';
        if (wid) card.setAttribute('data-widget-id', wid);
        card.setAttribute('role', 'status');
        card.setAttribute('aria-live', 'polite');
        card.style.cssText = `${fullWidth ? 'grid-column: 1 / -1; ' : ''}display: flex; flex-direction: column; align-items: center; justify-content: center; min-height: 220px; gap: 14px; color: var(--text-muted); background: var(--bg-surface); border-radius: 12px; border: 1px solid var(--border-subtle); padding: 32px 20px;`;
        const spinner = document.createElement('div');
        spinner.className = 'chart-spinner';
        const label = document.createElement('span');
        label.className = 'chart-loading-text';
        label.style.cssText = 'font-size: 0.875rem; font-weight: 600; color: var(--text-secondary); text-align: center;';
        label.textContent = title ? `Loading ${title}...` : 'Loading widget...';
        card.appendChild(spinner);
        card.appendChild(label);
        grid.appendChild(card);
        if (typeof window.applyWidgetEditModeUI === 'function') window.applyWidgetEditModeUI(page);
    };

    window.hydrateWidgetCharts = function (scopePage) {
        if (typeof Chart === 'undefined') return;
        applyCollapsedState();
        applyChartWidths();
        if (!scopePage || scopePage === 'overview') {
            const ov = getChartPayloads('overview');
            if (ov) {
                renderOvLifetimeForecast(ov);
                if (ov.cash_flow?.years?.length) getOrCreateChart('chart-ov-cashflow', () => makeCfConfig(ov.cash_flow));
                if (ov.monte_carlo?.years?.length) getOrCreateChart('chart-ov-montecarlo', () => makeMcConfig(ov.monte_carlo));
                const compCanvas = document.getElementById('chart-ov-career-comp');
                if (compCanvas) {
                    const compBody = compCanvas.closest('.collapsible-chart-body');
                    const oldEmpty = compBody && compBody.querySelector('.widget-chart-empty-msg');
                    if (oldEmpty) oldEmpty.remove();
                    if (ov.career_comp?.years?.length) {
                        compCanvas.style.display = '';
                        getOrCreateChart('chart-ov-career-comp', () => ({
                            type: 'bar',
                            data: {
                                labels: ov.career_comp.years,
                                datasets: [
                                    { label: 'Base Salary', data: ov.career_comp.base_salary || [], backgroundColor: '#3B82F6', stack: 'comp', order: 2 },
                                    { label: 'Bonus / Incentive', data: ov.career_comp.bonus || [], backgroundColor: '#F59E0B', stack: 'comp', order: 2 },
                                    { label: 'Total Comp', data: ov.career_comp.total_comp || [], type: 'line', borderColor: '#10B981', borderWidth: 2, pointRadius: 2, order: 1 }
                                ]
                            },
                            options: baseOpts()
                        }));
                    } else if (compBody) {
                        compCanvas.style.display = 'none';
                        const msg = document.createElement('div');
                        msg.className = 'widget-chart-empty-msg text-muted';
                        msg.style.cssText = 'display: flex; align-items: center; justify-content: center; height: 100%; font-size: 0.8125rem; text-align: center; padding: 20px;';
                        msg.textContent = 'No W-2 career compensation history on file for this household.';
                        compBody.appendChild(msg);
                    }
                }
                bindOverviewControls();
            }
        }
        if (!scopePage || scopePage === 'scenarios') {
            if (typeof window.renderActiveLensChart === 'function') {
                window.renderActiveLensChart();
            }
        }
    };

    document.addEventListener('click', (e) => {
        const wBtn = e.target.closest('.btn-toggle-chart-width');
        if (wBtn) { e.preventDefault(); toggleChartWidth(wBtn.getAttribute('data-chart-id')); return; }
        const btn = e.target.closest('.btn-toggle-chart-collapse');
        if (btn) { e.preventDefault(); toggleChartCollapse(btn.getAttribute('data-chart-id')); }
    });

    document.addEventListener('DOMContentLoaded', () => window.hydrateWidgetCharts());

    document.body.addEventListener('htmx:afterSettle', (e) => {
        const target = e.detail && e.detail.target;
        if (!target) { window.hydrateWidgetCharts(); return; }
        if (target.id === 'section-overview' || target.querySelector('#section-overview')) window.hydrateWidgetCharts('overview');
        else if (target.id === 'section-scenarios' || target.querySelector('#section-scenarios')) window.hydrateWidgetCharts('scenarios');
        else window.hydrateWidgetCharts();
    });
})();

;

/* --- Source: holdings.js --- */
;
/**
 * Holdings Inspector Module (SSR + HTMX/Idiomorph)
 * Delegates KPIs, execution simulator, IPS policy, private investments, and brokerage positions
 * to Jinja SSR in /fragments/holdings and morphs #section-holdings on state/CRUD changes.
 */

let holdingsAllocChart = null;

function getHoldingsDatasetTotals(data) {
    if (data && data.snapshot && data.snapshot.detailed_asset_allocation && data.snapshot.detailed_asset_allocation.totals) {
        const t = data.snapshot.detailed_asset_allocation.totals;
        const priv = (data.private_investments && data.private_investments.total_value !== undefined)
            ? data.private_investments.total_value
            : (t.private_investments || 0);
        return {
            us_equity: parseFloat(t.us_equity || 0),
            intl_equity: parseFloat(t.intl_equity || 0),
            bonds: parseFloat(t.bonds || 0),
            cash_liquid: parseFloat(t.cash_liquid || 0),
            real_estate_reits: parseFloat(t.real_estate_reits || 0),
            private_value: parseFloat(priv || 0)
        };
    }
    const sec = document.getElementById('section-holdings');
    if (!sec) {
        return { us_equity: 0, intl_equity: 0, bonds: 0, cash_liquid: 0, real_estate_reits: 0, private_value: 0 };
    }
    return {
        us_equity: parseFloat(sec.getAttribute('data-us-equity') || '0'),
        intl_equity: parseFloat(sec.getAttribute('data-intl-equity') || '0'),
        bonds: parseFloat(sec.getAttribute('data-bonds') || '0'),
        cash_liquid: parseFloat(sec.getAttribute('data-cash') || '0'),
        real_estate_reits: parseFloat(sec.getAttribute('data-real-estate') || '0'),
        private_value: parseFloat(sec.getAttribute('data-private') || '0')
    };
}

function getActiveHoldingsParams(overrides = {}) {
    const sec = document.getElementById('section-holdings');
    const preset = overrides.preset !== undefined ? overrides.preset : (sec?.getAttribute('data-preset') || 'core_satellite');
    const horizon = overrides.horizon !== undefined ? overrides.horizon : (sec?.getAttribute('data-horizon') || '10');
    const drift = overrides.drift !== undefined ? overrides.drift : (sec?.getAttribute('data-drift') || '0.05');
    return { preset, horizon, drift };
}

async function morphHoldingsSection(overrides = {}) {
    const { preset, horizon, drift } = getActiveHoldingsParams(overrides);
    const params = new URLSearchParams({
        preset: String(preset),
        horizon: String(horizon),
        drift: String(drift)
    });
    const url = `/fragments/holdings?${params.toString()}`;
    await window.htmx.ajax('GET', url, { target: '#section-holdings', swap: 'morph' });
    const totals = getHoldingsDatasetTotals();
    renderHoldingsAllocationChart(totals, totals.private_value, totals.real_estate_reits);
}

function renderHoldings(data) {
    setupHoldingsDelegation();
    const totals = getHoldingsDatasetTotals(data);
    renderHoldingsAllocationChart(totals, totals.private_value, totals.real_estate_reits);
}

function initHoldingsSection(data) {
    renderHoldings(data);
}

function renderHoldingsAllocationChart(totals = {}, privateValue, realEstateValue) {
    const canvas = document.getElementById('chart-holdings-asset-allocation');
    if (!canvas || typeof Chart === 'undefined') return;
    const ctx = canvas.getContext('2d');
    if (holdingsAllocChart) holdingsAllocChart.destroy();

    const usEquity = totals.us_equity || 0;
    const intlEquity = totals.intl_equity || 0;
    const bonds = totals.bonds || 0;
    const cash = totals.cash_liquid || 0;
    const privateTotal = privateValue !== undefined && privateValue !== null ? privateValue : (totals.private_value || 0);
    const reTotal = realEstateValue !== undefined && realEstateValue !== null ? realEstateValue : (totals.real_estate_reits || 0);
    const totalInvestments = usEquity + intlEquity + bonds + cash + privateTotal + reTotal;

    const badgeTotal = document.getElementById('holdings-pie-total-badge');
    if (badgeTotal) badgeTotal.textContent = `${fmtCurrency(totalInvestments, 0)} Total Portfolio`;

    holdingsAllocChart = new Chart(ctx, {
        type: 'doughnut',
        data: {
            labels: [
                'US Equities (Brokerage & 401k)',
                'International Equities',
                'Real Estate & REITs',
                'Private Investments & VC',
                'Bonds & Fixed Income',
                'Cash & Settlement Sweeps'
            ],
            datasets: [{
                data: [usEquity, intlEquity, reTotal, privateTotal, bonds, cash],
                backgroundColor: (window.CHART_THEME) ? [
                    window.CHART_THEME.emerald,
                    window.CHART_THEME.cerulean,
                    window.CHART_THEME.amber,
                    window.CHART_THEME.sapphire,
                    window.CHART_THEME.tanzanite,
                    window.CHART_THEME.slate
                ] : [
                    '#059669',
                    '#0284C7',
                    '#D97706',
                    '#1D4ED8',
                    '#7C3AED',
                    '#64748B'
                ],
                borderColor: '#161B26',
                borderWidth: 2
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: {
                    position: 'right',
                    labels: {
                        color: '#94A3B8',
                        font: { family: 'Inter', size: 11 },
                        padding: 12,
                        generateLabels: (chart) => {
                            const data = chart.data;
                            if (data.labels.length && data.datasets.length) {
                                return data.labels.map((label, i) => {
                                    const val = data.datasets[0].data[i];
                                    const pct = totalInvestments > 0 ? ((val / totalInvestments) * 100).toFixed(1) + '%' : '0%';
                                    return {
                                        text: `${label}: ${fmtShortCurrency(val)} (${pct})`,
                                        fillStyle: data.datasets[0].backgroundColor[i],
                                        strokeStyle: '#161B26',
                                        lineWidth: 1,
                                        index: i
                                    };
                                });
                            }
                            return [];
                        }
                    }
                },
                tooltip: {
                    callbacks: {
                        label: (ctx) => {
                            const pct = totalInvestments > 0 ? ((ctx.raw / totalInvestments) * 100).toFixed(1) : '0.0';
                            return ` ${ctx.label}: ${fmtCurrency(ctx.raw, 0)} (${pct}%)`;
                        }
                    }
                }
            },
            cutout: '60%'
        }
    });
}

function setupHoldingsDelegation() {
    if (document.body.dataset.holdingsDelegated === 'true') return;
    document.body.dataset.holdingsDelegated = 'true';

    document.addEventListener('click', async (e) => {
        const presetBtn = e.target.closest('.btn-sim-preset');
        if (presetBtn && presetBtn.closest('#section-holdings')) {
            const preset = presetBtn.getAttribute('data-preset') || 'core_satellite';
            await morphHoldingsSection({ preset });
            return;
        }

        const horizonBtn = e.target.closest('.btn-sim-horizon');
        if (horizonBtn && horizonBtn.closest('#section-holdings')) {
            const horizon = horizonBtn.getAttribute('data-horizon') || '10';
            await morphHoldingsSection({ horizon });
            return;
        }

        const savePolicyBtn = e.target.closest('#btn-save-investment-policy');
        if (savePolicyBtn) {
            const anchor = document.getElementById('select-anchor-preset')?.value || 'core_satellite';
            const driftVal = parseFloat(document.getElementById('select-drift-tolerance')?.value || '0.05');
            const rationale = document.getElementById('textarea-ips-deviations')?.value || '';
            const statusEl = document.getElementById('policy-save-status');

            if (statusEl) {
                statusEl.textContent = 'Saving...';
                statusEl.style.color = 'var(--text-muted)';
            }

            try {
                const resp = await fetch('/api/holdings/policy', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        anchor_preset: anchor,
                        drift_tolerance: driftVal,
                        deviations_rationale: rationale
                    })
                });
                const res = await resp.json();
                if (res.success) {
                    const sec = document.getElementById('section-holdings');
                    if (sec) {
                        sec.dataset.preset = anchor;
                        sec.dataset.drift = driftVal.toFixed(2);
                    }
                    if (!window.__DOMAIN_VERSIONS__) {
                        await morphHoldingsSection({ preset: anchor, drift: driftVal.toFixed(2) });
                    }
                    const newStatusEl = document.getElementById('policy-save-status');
                    if (newStatusEl) {
                        newStatusEl.textContent = '✓ Policy Saved';
                        newStatusEl.style.color = 'var(--status-green)';
                        setTimeout(() => { if (newStatusEl) newStatusEl.textContent = ''; }, 3000);
                    }
                } else if (statusEl) {
                    statusEl.textContent = res.error || 'Save failed';
                    statusEl.style.color = 'var(--status-red)';
                }
            } catch (err) {
                if (statusEl) {
                    statusEl.textContent = 'Error saving policy';
                    statusEl.style.color = 'var(--status-red)';
                }
            }
            return;
        }
    });

    document.addEventListener('change', async (e) => {
        const selDrift = e.target.closest('#select-drift-tolerance');
        if (selDrift && selDrift.closest('#section-holdings')) {
            const drift = parseFloat(selDrift.value || '0.05').toFixed(2);
            await morphHoldingsSection({ drift });
        }
    });

    document.addEventListener('input', (e) => {
        if (e.target.id === 'lp-input-total-commitment' || e.target.id === 'lp-input-capital-called') {
            const tot = parseFloat(document.getElementById('lp-input-total-commitment')?.value) || 0;
            const cal = parseFloat(document.getElementById('lp-input-capital-called')?.value) || 0;
            const unfEl = document.getElementById('lp-input-unfunded');
            if (unfEl) {
                unfEl.value = Math.max(0, tot - cal);
            }
        }
    });
}

function openLpCommitmentModal(item = null) {
    const modal = document.getElementById('modal-lp-commitment');
    if (!modal) return;
    const title = document.getElementById('modal-lp-title');
    const delBtn = document.getElementById('btn-delete-lp');

    document.getElementById('lp-input-id').value = item?.id || '';
    document.getElementById('lp-input-account-id').value = item?.account_id || '';
    document.getElementById('lp-input-fund-name').value = item?.fund_name || '';
    document.getElementById('lp-input-fund-type').value = item?.fund_type || 'Private Equity';
    document.getElementById('lp-input-vintage-year').value = item?.vintage_year || 2022;
    document.getElementById('lp-input-total-commitment').value = item?.total_commitment || '';
    document.getElementById('lp-input-capital-called').value = item?.capital_called !== undefined ? item.capital_called : '';
    document.getElementById('lp-input-unfunded').value = item?.unfunded_commitment !== undefined ? item.unfunded_commitment : '';
    document.getElementById('lp-input-horizon').value = item?.expected_call_horizon_years || 3;
    document.getElementById('lp-input-current-nav').value = item?.current_nav !== undefined ? item.current_nav : '';
    document.getElementById('lp-input-distributions').value = item?.distributions_received !== undefined ? item.distributions_received : '';
    document.getElementById('lp-input-last-mark-date').value = item?.last_mark_date || '';
    document.getElementById('lp-input-k1-status').value = item?.k1_status || 'Expected';
    document.getElementById('lp-input-notes').value = item?.notes || '';

    if (title) title.textContent = item ? `Edit LP Commitment: ${item.fund_name || ''}` : 'Annotate Private Investment / LP Commitment';
    if (delBtn) delBtn.style.display = item && item.id && !String(item.id).startsWith('lp_demo_') ? 'inline-block' : 'none';

    modal.style.display = 'flex';
}

function closeLpCommitmentModal() {
    const modal = document.getElementById('modal-lp-commitment');
    if (modal) modal.style.display = 'none';
}

async function saveLpCommitment() {
    const totalC = parseFloat(document.getElementById('lp-input-total-commitment')?.value) || 0;
    const calledC = parseFloat(document.getElementById('lp-input-capital-called')?.value) || 0;
    const unfundedVal = document.getElementById('lp-input-unfunded')?.value;
    const unfundedC = unfundedVal !== '' && !isNaN(parseFloat(unfundedVal)) ? parseFloat(unfundedVal) : Math.max(0, totalC - calledC);

    const payload = {
        id: document.getElementById('lp-input-id')?.value || '',
        account_id: document.getElementById('lp-input-account-id')?.value || '',
        fund_name: document.getElementById('lp-input-fund-name')?.value || 'Private Fund',
        fund_type: document.getElementById('lp-input-fund-type')?.value || 'Private Equity',
        vintage_year: parseInt(document.getElementById('lp-input-vintage-year')?.value) || 2022,
        total_commitment: totalC,
        capital_called: calledC,
        unfunded_commitment: unfundedC,
        expected_call_horizon_years: parseInt(document.getElementById('lp-input-horizon')?.value) || 3,
        current_nav: parseFloat(document.getElementById('lp-input-current-nav')?.value) || 0,
        distributions_received: parseFloat(document.getElementById('lp-input-distributions')?.value) || 0,
        last_mark_date: document.getElementById('lp-input-last-mark-date')?.value || '',
        k1_status: document.getElementById('lp-input-k1-status')?.value || 'Expected',
        notes: document.getElementById('lp-input-notes')?.value || '',
    };

    const saveBtn = document.getElementById('btn-save-lp');
    if (saveBtn) { saveBtn.disabled = true; saveBtn.textContent = 'Saving...'; }

    try {
        const resp = await fetch('/api/holdings/lp_commitments', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        const res = await resp.json();
        if (res.success) {
            closeLpCommitmentModal();
            await morphHoldingsSection();
        } else {
            alert(res.error || 'Failed to save LP commitment');
        }
    } catch (err) {
        alert('Network error saving LP commitment');
    } finally {
        if (saveBtn) { saveBtn.disabled = false; saveBtn.textContent = 'Save Commitment'; }
    }
}

async function deleteActiveLpCommitment() {
    const id = document.getElementById('lp-input-id')?.value;
    if (!id || !confirm('Are you sure you want to delete this LP commitment annotation?')) return;
    try {
        const resp = await fetch(`/api/holdings/lp_commitments/${encodeURIComponent(id)}`, { method: 'DELETE' });
        const res = await resp.json();
        if (res.success) {
            closeLpCommitmentModal();
            await morphHoldingsSection();
        } else {
            alert(res.error || 'Failed to delete LP commitment');
        }
    } catch (err) {
        alert('Network error deleting LP commitment');
    }
}

setupHoldingsDelegation();

if (typeof window !== 'undefined') {
    Object.assign(window, {
        renderHoldings,
        initHoldingsSection,
        morphHoldingsSection,
        renderHoldingsAllocationChart,
        openLpCommitmentModal,
        closeLpCommitmentModal,
        saveLpCommitment,
        deleteActiveLpCommitment
    });
    if (typeof window.registerSectionHydrator === 'function') {
        window.registerSectionHydrator('section-holdings', renderHoldings, {
            needsDashboard: true,
            morphFn: () => morphHoldingsSection()
        });
    }
}

;

/* --- Source: equity_chart_helpers.js --- */
;
/**
 * Equity Chart Helpers & Sensitivity / Trajectory Chart Renderers
 * Extracted from static/js/equity_chart.js for modular separation.
 */

var equityStockChart = null;
var equityGraphMode = 'fmv'; // 'fmv' (default), 'trajectory', or 'curve'
var currentSimulatedPrice = 0;
var currentIncludeWaTax = false;
var equityGrantsData = [];
var equityProjectionsData = [];
var equityFmvHistoryData = [];
var currentEquityData = null;
var debounceScenarioTimer = null;
var activeEquityCompanyId = null;
var currentPortfolioMultiple = 1.0;
var equityCompaniesList = [];

var DEFAULT_FMV_HISTORY = [];

function setStat(labelEl, labelText, valEl, valText, color, subEl, subText) {
    if (labelEl) labelEl.textContent = labelText;
    if (valEl) {
        valEl.textContent = valText;
        if (color) valEl.style.color = color;
    }
    if (subEl) subEl.textContent = subText;
}

function getVestedUnitsAsOfDate(dateStr, grants) {
    if (!grants || grants.length === 0) return 0;
    const targetTime = new Date(dateStr).getTime();
    if (isNaN(targetTime)) return 0;
    let totalUnits = 0;

    grants.forEach(g => {
        if (!g.grant_date) return;
        const gTime = new Date(g.grant_date).getTime();
        if (isNaN(gTime) || targetTime < gTime) return;

        let vTime;
        if (g.fully_vested_date) {
            vTime = new Date(g.fully_vested_date).getTime();
        } else {
            const d = new Date(g.grant_date);
            d.setFullYear(d.getFullYear() + 4);
            vTime = d.getTime();
        }

        const vestedOptions = Number(g.unexercised_options || g.unexercised_vested || 0);
        const ownedShares = Number(g.owned_shares || g.owned_exercised || 0);
        const unvestedOptions = Number(g.unvested_options || g.unvested || 0);
        const activeGrantUnits = vestedOptions + ownedShares + unvestedOptions;

        if (targetTime >= vTime) {
            totalUnits += (vestedOptions + ownedShares);
        } else {
            const totalDuration = Math.max(1, vTime - gTime);
            const elapsed = Math.max(0, targetTime - gTime);
            const vestFraction = Math.min(1.0, elapsed / totalDuration);
            totalUnits += Math.round(vestFraction * activeGrantUnits);
        }
    });

    return totalUnits;
}

function updateGraphHeaderAndStats(equity, currentPrice) {
    const v = equity || currentEquityData || {};
    const isConsolidated = (activeEquityCompanyId === 'all');
    const comp = !isConsolidated ? equityCompaniesList.find(c => Number(c.company_id) === Number(activeEquityCompanyId)) : null;
    const compName = isConsolidated ? 'Portfolio' : ((comp && comp.company_name) || (v && v.company_name) || 'Company');
    const price = currentPrice || currentSimulatedPrice || (v && v.share_price) || 0;

    const titleEl = document.getElementById('equity-graph-title');
    const subtitleEl = document.getElementById('equity-graph-subtitle');
    const l1 = document.getElementById('graph-stat-label-1'), s1 = document.getElementById('graph-stat-gross'), sub1 = document.getElementById('graph-stat-sub-1');
    const l2 = document.getElementById('graph-stat-label-2'), s2 = document.getElementById('graph-stat-net'), sub2 = document.getElementById('graph-stat-sub-2');
    const l3 = document.getElementById('graph-stat-label-3'), s3 = document.getElementById('graph-stat-strike'), sub3 = document.getElementById('graph-stat-sub-3');
    const l4 = document.getElementById('graph-stat-label-4'), sGrowth = document.getElementById('graph-stat-growth'), sub4 = document.getElementById('graph-stat-sub-4');
    const l5 = document.getElementById('graph-stat-label-5'), s5 = document.getElementById('graph-stat-tax'), sub5 = document.getElementById('graph-stat-sub-5');

    const historyItems = (equityFmvHistoryData && equityFmvHistoryData.length > 0)
        ? equityFmvHistoryData
        : ((v && v.fmv_history && v.fmv_history.length > 0) ? v.fmv_history : []);
    const firstFmv = historyItems.length > 0 ? historyItems[0] : null;

    const selExpectedGrowth = document.getElementById('select-equity-expected-growth');
    const growthRate = selExpectedGrowth ? parseFloat(selExpectedGrowth.value) : 0.105;
    const growthPctStr = `+${(growthRate * 100).toFixed(1)}%/yr`;
    const isBaseline = Math.abs(growthRate - 0.105) < 0.001;
    const hasEquityData = price > 0 || (equityCompaniesList && equityCompaniesList.length > 0) || (equityGrantsData && equityGrantsData.length > 0) || historyItems.length > 0;

    const grossVal = isConsolidated ? (v.nominal_gross_equity_value || v.total_gross_equity_value || 0) : (v.company_nominal_gross_equity_value !== undefined ? v.company_nominal_gross_equity_value : (v.company_gross_equity_value || v.total_gross_equity_value || 0));
    const netVal = isConsolidated ? (v.true_net_post_tax_value || 0) : (v.company_true_net_post_tax_value !== undefined ? v.company_true_net_post_tax_value : (v.true_net_post_tax_value || 0));
    const strikeVal = isConsolidated ? (v.total_strike_cost_needed || 0) : (v.company_strike_cost_needed !== undefined ? v.company_strike_cost_needed : (v.total_strike_cost_needed || 0));
    const taxVal = isConsolidated ? (v.total_tax_drag || 0) : (v.company_tax_drag !== undefined ? v.company_tax_drag : (v.total_tax_drag || 0));

    if (equityGraphMode === 'fmv') {
        if (titleEl) titleEl.textContent = `${compName} 409A Fair Market Value (FMV) Over Time & Projections`;
        if (subtitleEl) {
            subtitleEl.textContent = !hasEquityData ? 'Historical 409A valuation path by date with forward compound projections.'
                : (isConsolidated ? `Historical 409A valuation path for primary holdings with forward compound projections @ ${growthPctStr}.`
                : `Historical 409A valuation path for ${compName} with forward compound projections @ ${growthPctStr} (${isBaseline ? 'Forecasting Baseline' : 'Selected Growth'}).`);
        }
        setStat(l1, firstFmv ? `INITIAL 409A (${firstFmv.date || ''}):` : 'INITIAL 409A:', s1, firstFmv ? fmtCurrency(firstFmv.price, 2) : '--', '#3B82F6', sub1, firstFmv ? (firstFmv.notes || 'Initial recorded grant') : 'Historical baseline');
        setStat(l2, isConsolidated ? 'SIMULATED MULTIPLE:' : 'CURRENT 409A FMV:', s2, isConsolidated ? `${currentPortfolioMultiple.toFixed(2)}x` : (price > 0 ? fmtCurrency(price, 2) : '--'), '#10B981', sub2, isConsolidated ? 'Applied across holdings' : 'Verified 409A baseline');
        setStat(l4, 'EXPECTED FUTURE GROWTH:', sGrowth, hasEquityData ? growthPctStr : '--', 'var(--brand-primary, #0265E8)', sub4, hasEquityData ? (isBaseline ? 'Forecasting Baseline' : 'Selected Scenario Rate') : 'No 409A data recorded');
        const proj5yr = price * Math.pow(1 + growthRate, 5);
        const gainPct = ((Math.pow(1 + growthRate, 5) - 1) * 100).toFixed(1);
        setStat(l5, 'PROJECTED 5-YR FMV:', s5, price > 0 ? fmtCurrency(proj5yr, 2) : '--', '#10B981', sub5, price > 0 ? `+${gainPct}% gain @ ${growthPctStr}` : '--');
    } else if (equityGraphMode === 'trajectory') {
        if (titleEl) titleEl.textContent = `${compName} Multi-Year Equity & Tax Trajectory`;
        if (subtitleEl) subtitleEl.textContent = `Projected gross, net post-tax, and unvested option transitions assuming ${growthPctStr} annual growth.`;
        setStat(l1, 'EST. GROSS VALUE:', s1, fmtCurrency(grossVal, 0), '#3B82F6', sub1, 'Vested equity only');
        setStat(l2, 'TRUE NET PROCEEDS:', s2, fmtCurrency(netVal, 0), '#10B981', sub2, 'Take-home liquidity');
        setStat(l3, 'STRIKE CAPITAL REQ:', s3, fmtCurrency(strikeVal, 0), '#F59E0B', sub3, 'Exercise obligation');
        setStat(l4, 'EXPECTED GROWTH MODEL:', sGrowth, hasEquityData ? growthPctStr : '--', 'var(--brand-primary, #0265E8)', sub4, hasEquityData ? (isBaseline ? 'Forecasting Baseline' : 'Selected Growth Preset') : 'No 409A data recorded');
        setStat(l5, 'TAX LIABILITY DRAG:', s5, fmtCurrency(taxVal, 0), '#EF4444', sub5, 'Ordinary + LTCG + State');
    } else { // 'curve'
        if (titleEl) titleEl.textContent = `${compName} Valuation Sensitivity Curve`;
        if (subtitleEl) subtitleEl.textContent = `Net liquidation proceeds vs. total tax liability across potential ${compName} valuation scenarios.`;
        setStat(l1, 'SIMULATED GROSS:', s1, fmtCurrency(grossVal, 0), '#3B82F6', sub1, 'At slider level');
        setStat(l2, 'SIMULATED NET:', s2, fmtCurrency(netVal, 0), '#10B981', sub2, 'Take-home liquidity');
        setStat(l3, 'TOTAL STRIKE COST:', s3, fmtCurrency(strikeVal, 0), '#F59E0B', sub3, 'Exercise obligation');
        setStat(l4, 'BASELINE GROWTH:', sGrowth, hasEquityData ? '+10.5% / yr' : '--', '#8B5CF6', sub4, hasEquityData ? 'Forecasting Baseline' : 'No 409A data recorded');
        setStat(l5, 'TOTAL TAX DRAG:', s5, fmtCurrency(taxVal, 0), '#EF4444', sub5, 'Federal + WA SB 6346');
    }
}

function renderTrajectoryChart(ctx, equityProjectionsData) {
    const labels = equityProjectionsData.map(p => `Year ${p.year}`);
    const grossData = equityProjectionsData.map(p => p.gross_equity);
    const netData = equityProjectionsData.map(p => p.true_net_equity);
    const taxData = equityProjectionsData.map(p => p.total_tax_drag);
    const unvestedData = equityProjectionsData.map(p => p.unvested_net_value || 0);

    const theme = window.CHART_THEME;
    return new Chart(ctx, {
        type: 'line',
        data: {
            labels: labels,
            datasets: [
                {
                    label: 'Gross Stock & Option Value',
                    data: grossData,
                    borderColor: (theme && theme.equity.gross) || '#1D4ED8',
                    backgroundColor: (theme && theme.equity.grossFill) || 'rgba(29, 78, 216, 0.1)',
                    fill: true,
                    tension: 0.3,
                    borderWidth: 2,
                },
                {
                    label: 'True Net Post-Tax Proceeds (Vested)',
                    data: netData,
                    borderColor: (theme && theme.equity.net) || '#059669',
                    backgroundColor: (theme && theme.equity.netFill) || 'rgba(5, 150, 105, 0.15)',
                    fill: true,
                    tension: 0.3,
                    borderWidth: 3,
                },
                {
                    label: 'Unvested Options Value (Excluded until Vested)',
                    data: unvestedData,
                    borderColor: (theme && theme.equity.unvested) || '#D97706',
                    backgroundColor: (theme && theme.alpha(theme.amber, 0.08)) || 'rgba(217, 119, 6, 0.08)',
                    borderDash: [5, 4],
                    fill: false,
                    tension: 0.3,
                    borderWidth: 2,
                },
                {
                    label: 'Tax Drag',
                    data: taxData,
                    borderColor: (theme && theme.equity.taxDrag) || '#E11D48',
                    borderDash: [5, 5],
                    borderWidth: 2,
                    tension: 0.3,
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: { position: 'top', labels: { color: '#94A3B8', font: { family: 'Inter', size: 11 } } },
                tooltip: { callbacks: { label: (c) => ` ${c.dataset.label}: ${fmtShortCurrency(c.raw)}` } }
            },
            scales: {
                x: { grid: { color: 'rgba(255, 255, 255, 0.05)' }, ticks: { color: '#94A3B8' } },
                y: { grid: { color: 'rgba(255, 255, 255, 0.05)' }, ticks: { color: '#94A3B8', callback: (v) => fmtShortCurrency(v) } }
            }
        }
    });
}

function renderCurveChart(ctx, grants, currentPrice, activeEquity, includeWaTax) {
    let totalOptions = 0.0, ownedShares = 0.0, strikeCost = 0.0, ownedCostBasisTotal = 0.0, unvestedOptions = 0.0, unvestedStrikeCost = 0.0;
    grants.forEach(g => {
        const vested = Number(g.unexercised_vested || g.unexercised_options || 0);
        const owned = Number(g.owned_exercised || g.owned_shares || 0);
        const unv = Number(g.unvested || g.unvested_options || 0);
        const strike = Number(g.strike_price || 0);
        const basis = Number(g.historical_cost_basis || (strike > 0 ? strike : 0));
        totalOptions += vested;
        ownedShares += owned;
        strikeCost += (vested * strike);
        ownedCostBasisTotal += (owned * basis);
        unvestedOptions += unv;
        unvestedStrikeCost += (unv * strike);
    });

    const totalShares = totalOptions + ownedShares;
    const baseP = currentPrice || (activeEquity && activeEquity.share_price) || 2500;
    const samplePrices = [0.5, 0.75, 1.0, 1.25, 1.5, 2.0, 2.5, 3.0, 4.0, 5.0].map(m => Math.round(baseP * m));

    const grossPoints = [], netPoints = [], taxPoints = [], strikePoints = [], unvestedPoints = [];
    samplePrices.forEach(p => {
        const gross = (totalShares * p);
        const spread = Math.max(0, (totalOptions * p) - strikeCost);
        const ownedGain = Math.max(0, (ownedShares * p) - ownedCostBasisTotal);
        const fedRate = 0.3935;
        const waRate = includeWaTax ? 0.099 : (spread > 1000000 ? 0.07 : 0.0);
        const optTax = spread * (fedRate + waRate);
        const stockTax = ownedGain * 0.238;
        const totalTax = optTax + stockTax;
        const net = (spread - optTax) + (ownedShares * p - stockTax);

        const uSpread = Math.max(0, (unvestedOptions * p) - unvestedStrikeCost);
        const uWaRate = includeWaTax ? 0.099 : (uSpread > 1000000 ? 0.07 : 0.0);
        const uTax = uSpread * (fedRate + uWaRate);
        const uNet = Math.max(0, uSpread - uTax);

        grossPoints.push(Math.round(gross));
        netPoints.push(Math.round(net));
        taxPoints.push(Math.round(totalTax));
        strikePoints.push(Math.round(strikeCost));
        unvestedPoints.push(Math.round(uNet));
    });

    const labels = samplePrices.map(p => `$${p.toLocaleString()}`);
    const theme = window.CHART_THEME;
    const grossColor = (theme && theme.equity.gross) || '#1D4ED8';
    const grossFill = (theme && theme.equity.grossFill) || 'rgba(29, 78, 216, 0.08)';
    const netColor = (theme && theme.equity.net) || '#059669';
    const netFill = (theme && theme.equity.netFill) || 'rgba(5, 150, 105, 0.12)';
    const unvestedColor = (theme && theme.equity.unvested) || '#D97706';
    const taxColor = (theme && theme.equity.taxDrag) || '#E11D48';
    const highlightColor = (theme && theme.equity.pointHighlight) || '#D97706';

    return new Chart(ctx, {
        type: 'line',
        data: {
            labels: labels,
            datasets: [
                {
                    label: 'Gross Stock Value ($M)',
                    data: grossPoints,
                    borderColor: grossColor,
                    backgroundColor: grossFill,
                    fill: true,
                    tension: 0.25,
                    borderWidth: 2,
                    pointRadius: samplePrices.map(p => Math.abs(p - currentPrice) < 150 ? 7 : 3),
                    pointBackgroundColor: samplePrices.map(p => Math.abs(p - currentPrice) < 150 ? highlightColor : grossColor),
                },
                {
                    label: 'True Net Post-Tax Proceeds (Vested)',
                    data: netPoints,
                    borderColor: netColor,
                    backgroundColor: netFill,
                    fill: true,
                    tension: 0.25,
                    borderWidth: 3,
                    pointRadius: samplePrices.map(p => Math.abs(p - currentPrice) < 150 ? 8 : 4),
                    pointBackgroundColor: samplePrices.map(p => Math.abs(p - currentPrice) < 150 ? highlightColor : netColor),
                },
                {
                    label: 'Unvested Options Net Value (Excluded from NW)',
                    data: unvestedPoints,
                    borderColor: unvestedColor,
                    borderDash: [5, 4],
                    borderWidth: 2,
                    tension: 0.25,
                    pointRadius: 2,
                },
                {
                    label: 'Total Tax Liability Drag',
                    data: taxPoints,
                    borderColor: taxColor,
                    borderDash: [4, 4],
                    borderWidth: 2,
                    tension: 0.25,
                    pointRadius: 2,
                },
                {
                    label: 'Strike Obligation',
                    data: strikePoints,
                    borderColor: unvestedColor,
                    borderDash: [6, 4],
                    borderWidth: 2,
                    tension: 0,
                    pointRadius: 0,
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            interaction: { mode: 'index', intersect: false },
            plugins: {
                legend: { position: 'top', labels: { color: '#94A3B8', font: { family: 'Inter', size: 11 }, padding: 12 } },
                tooltip: { callbacks: { label: (c) => ` ${c.dataset.label}: ${fmtShortCurrency(c.raw)}` } }
            },
            scales: {
                x: { grid: { color: 'rgba(255, 255, 255, 0.05)' }, ticks: { color: '#94A3B8', font: { size: 10 } } },
                y: { grid: { color: 'rgba(255, 255, 255, 0.05)' }, ticks: { color: '#94A3B8', callback: (v) => fmtShortCurrency(v) } }
            }
        }
    });
}

if (typeof window !== 'undefined') {
    Object.assign(window, {
        setStat,
        getVestedUnitsAsOfDate,
        updateGraphHeaderAndStats,
        renderTrajectoryChart,
        renderCurveChart,
        DEFAULT_FMV_HISTORY,
    });
}

